style.css:
@-moz-document domain("google.com") {
:root {
    /* Change these colors to customize the darkness */
    --my-bg: #000000;
    --my-card: #050505;
    --my-border: #151515;
    --my-text: #dedede;
    --my-muted: #888888;
    --my-link: #aaaaff;
}

/* main background */
html, body {
    background: var(--my-bg) !important;
    color: var(--my-text) !important;
}

/* search result cards */
.result-card,
.search-result,
.card {
    background: var(--my-card) !important;
    border: 1px solid var(--my-border) !important;
    color: var(--my-text) !important;
    box-shadow: none !important;
}

/* result titles and descriptions */
.result-card *,
.search-result *,
.card * {
    color: var(--my-text) !important;
}

/* search links */
a {
    color: var(--my-link) !important;
}

/* search input */
input,
.search-bar {
    background: #050505 !important;
    color: #ffffff !important;
    border: 1px solid #1a1a1a !important;
}

/* subtle hover effect */
.result-card:hover,
.search-result:hover,
.card:hover {
    background: #0b0b0b !important;
    border-color: #292929 !important;
}
}
